import java.util.*;

class Solution {
    public boolean isValidSudoku(char[][] board) {
        boolean[][] row = new boolean[9][10];
        boolean[][] col = new boolean[9][10];
        boolean[][] box = new boolean[9][10];
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') continue;     // empty cell
                int d = board[r][c] - '0';
                int b = (r / 3) * 3 + c / 3;          // which 3x3 box
                if (row[r][d] || col[c][d] || box[b][d]) return false;   // seen before
                row[r][d] = true;
                col[c][d] = true;
                box[b][d] = true;
            }
        }
        return true;
    }
}

