class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        seen = set()
        for r in range(9):
            for c in range(9):
                d = board[r][c]
                if d == ".": continue
                keys = (("r", r, d), ("c", c, d), ("b", (r // 3) * 3 + c // 3, d))
                for k in keys:
                    if k in seen: return False
                    seen.add(k)
        return True

