function isValidSudoku(board) {
  const ok = cells => { const d = cells.filter(x => x !== "."); return new Set(d).size === d.length; };
  for (let i = 0; i < 9; i++) {
    if (!ok(board[i])) return false;
    if (!ok(board.map(row => row[i]))) return false;
    const box = [];
    for (let k = 0; k < 9; k++) box.push(board[Math.floor(i / 3) * 3 + Math.floor(k / 3)][(i % 3) * 3 + k % 3]);
    if (!ok(box)) return false;
  }
  return true;
}
